import subprocess
snapshot='backup/pre-linear-sync-a8dde56dc2'
def git(*args,check=True):
    return subprocess.run(['git',*args],text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,check=check)
for step in range(80):
    if git('rev-parse','--verify','REBASE_HEAD',check=False).returncode:
        print('Rebase completed',flush=True)
        break
    current=git('show','-s','--format=%h %s','REBASE_HEAD').stdout.strip()
    paths=git('diff','--name-only','--diff-filter=U','-z').stdout.split('\0')
    paths=[p for p in paths if p]
    for path in paths:
        if git('cat-file','-e',f'{snapshot}:{path}',check=False).returncode == 0:
            git('restore',f'--source={snapshot}','--staged','--worktree','--',path)
        else:
            git('rm','-f','--',path)
    print(f'{current}: reused verified resolutions for {len(paths)} files',flush=True)
    action='--skip' if git('diff','--cached','--quiet',check=False).returncode == 0 else '--continue'
    result=git('-c','core.editor=true','rebase',action,check=False)
    print(result.stdout[-1800:],flush=True)
    if result.returncode and not git('diff','--name-only','--diff-filter=U').stdout.strip():
        raise SystemExit('Stopped on non-conflict rebase error; inspect before continuing')
else:
    raise SystemExit('Rebase iteration limit exceeded')
